import prettier from "prettier";

/**
 * The canonical shape the fixture is rendered from. Only the field the
 * renderer validates is named; it copies the rest through verbatim.
 */
interface CanonicalClientSchemaDescriptor {
  readonly collections: readonly unknown[];
  readonly [key: string]: unknown;
}

const CLIENT_SCHEMA_FIXTURE_BANNER =
  "// Generated by scripts/check-client-generated-schema-fixture.ts. DO NOT EDIT.";

export async function renderClientSchemaFixture(
  descriptor: unknown,
): Promise<string> {
  assertCanonicalDescriptor(descriptor);
  const source = `${CLIENT_SCHEMA_FIXTURE_BANNER}
import { createGeneratedClientSchema } from "@calque/client/generated";

export const schema = createGeneratedClientSchema(${JSON.stringify(
    descriptor,
    null,
    2,
  )});
`;
  return prettier.format(source, {
    parser: "typescript",
    endOfLine: "lf",
  });
}

function assertCanonicalDescriptor(
  descriptor: unknown,
): asserts descriptor is CanonicalClientSchemaDescriptor {
  if (descriptor === null || typeof descriptor !== "object") {
    throw new TypeError("canonical client schema descriptor is invalid");
  }
  const candidate = descriptor as Record<string, unknown>;
  if (Array.isArray(descriptor) || !Array.isArray(candidate.collections)) {
    throw new TypeError("canonical client schema descriptor is invalid");
  }
}
